88	            new WeightRampingUpStrategy(defaultTransition, () -> CommonPools.workerGroup().next(),
89	                                        DEFAULT_RAMPING_UP_INTERVAL_MILLIS, DEFAULT_TOTAL_STEPS,
90	                                        DEFAULT_RAMPING_UP_TASK_WINDOW_MILLIS, defaultTicker);
91	
92	    private final EndpointWeightTransition weightTransition;
93	    private final Supplier<EventExecutor> executorSupplier;
94	    private final long rampingUpIntervalNanos;
95	    private final int totalSteps;
96	    private final long rampingUpTaskWindowNanos;
97	    private final Ticker ticker;
98	
99	    WeightRampingUpStrategy(EndpointWeightTransition weightTransition,
100	                            Supplier<EventExecutor> executorSupplier, long rampingUpIntervalMillis,
101	                            int totalSteps, long rampingUpTaskWindowMillis) {
102	        this(weightTransition, executorSupplier, rampingUpIntervalMillis, totalSteps,
103	             rampingUpTaskWindowMillis, defaultTicker);
104	    }
105	
106	    @VisibleForTesting
107	    WeightRampingUpStrategy(EndpointWeightTransition weightTransition,
108	                            Supplier<EventExecutor> executorSupplier, long rampingUpIntervalMillis,
109	                            int totalSteps, long rampingUpTaskWindowMillis, Ticker ticker) {
110	        this.weightTransition = requireNonNull(weightTransition, "weightTransition");
111	        this.executorSupplier = requireNonNull(executorSupplier, "executorSupplier");
112	        checkArgument(rampingUpIntervalMillis > 0,
113	                      "rampingUpIntervalMillis: %s (expected: > 0)", rampingUpIntervalMillis);
114	        rampingUpIntervalNanos = TimeUnit.MILLISECONDS.toNanos(rampingUpIntervalMillis);
115	        checkArgument(totalSteps > 0, "totalSteps: %s (expected: > 0)", totalSteps);
116	        this.totalSteps = totalSteps;
117	        checkArgument(rampingUpTaskWindowMillis >= 0,
118	                      "rampingUpTaskWindowMillis: %s (expected: > 0)",
119	                      rampingUpTaskWindowMillis);
120	        rampingUpTaskWindowNanos = TimeUnit.MILLISECONDS.toNanos(rampingUpTaskWindowMillis);
121	        this.ticker = requireNonNull(ticker, "ticker");
