36	        return endpoints.stream().map(Entry::new).collect(ImmutableList.toImmutableList());
37	    }
38	
39	    @Nullable
40	    Endpoint selectEndpoint() {
41	        final Entry entry = select();
42	        if (entry == null) {
43	            return null;
44	        }
45	        return entry.endpoint();
46	    }
