25	/**
26	 * Computes the weight of the given {@link Endpoint} using the given {@code currentStep}
27	 * and {@code totalSteps}.
28	 */
29	@FunctionalInterface
30	public interface EndpointWeightTransition {
31	
32	    /**
33	     * Returns the {@link EndpointWeightTransition} which returns the gradually increased weight as the current
34	     * step increases.
35	     */
36	    static EndpointWeightTransition linear() {
37	        return DEFAULT_LINEAR_TRANSITION;
38	    }
39	
40	    /**
41	     * Returns an {@link EndpointWeightTransition} which returns a non-linearly increasing weight
42	     * based on an aggression factor. Higher aggression factors will assign higher weights for lower steps.
43	     * You may also specify a {@code minWeightPercent} to specify a lower bound for the computed weights.
44	     * Refer to the following
45	     * <a href="https://www.envoyproxy.io/docs/envoy/latest/intro/arch_overview/upstream/load_balancing/slow_start">link</a>
46	     * for more information.
47	     */
48	    static EndpointWeightTransition aggression(double aggression, double minWeightPercent) {
49	        checkArgument(aggression > 0,
50	                      "aggression: %s (expected: > 0.0)", aggression);
51	        checkArgument(minWeightPercent >= 0 && minWeightPercent <= 1.0,
52	                      "minWeightPercent: %s (expected: >= 0.0, <= 1.0)", minWeightPercent);
53	        final int aggressionPercentage = Ints.saturatedCast(Math.round(aggression * 100));
54	        final double invertedAggression = 100.0 / aggressionPercentage;
55	        return (endpoint, currentStep, totalSteps) -> {
56	            final int weight = endpoint.weight();
57	            final int minWeight = Ints.saturatedCast(Math.round(weight * minWeightPercent));
58	            final int computedWeight;
59	            if (aggressionPercentage == 100) {
60	                computedWeight = linear().compute(endpoint, currentStep, totalSteps);
61	            } else {
62	                computedWeight = (int) (weight * Math.pow(1.0 * currentStep / totalSteps, invertedAggression));
63	            }
64	            return Math.max(computedWeight, minWeight);
65	        };
66	    }
67	
68	    /**
69	     * Returns the computed weight of the given {@link Endpoint} using the given {@code currentStep} and
70	     * {@code totalSteps}.
71	     */
72	    int compute(Endpoint endpoint, int currentStep, int totalSteps);
