31	/**
32	 * An {@link EndpointSelector} strategy which implements sticky load-balancing using
33	 * user passed {@link ToLongFunction} to compute hashes for consistent hashing.
34	 *
35	 * <p>This strategy can be useful when all requests that qualify some given criteria must be sent to the same
36	 * backend server. A common use case is to send all requests for the same logged-in user to the same backend,
37	 * which could have a local cache keyed by user id.
38	 *
39	 * <p>In below example, created strategy will route all {@link HttpRequest} which have the same value for key
40	 * "cookie" of its header to the same server:
41	 *
42	 * <pre>{@code
43	 * ToLongFunction<ClientRequestContext> hasher = (ClientRequestContext ctx) -> {
44	 *     return ((HttpRequest) ctx.request()).headers().get(HttpHeaderNames.COOKIE).hashCode();
45	 * };
46	 * final StickyEndpointSelectionStrategy strategy = new StickyEndpointSelectionStrategy(hasher);
47	 * }</pre>
48	 */
49	final class StickyEndpointSelectionStrategy implements EndpointSelectionStrategy {
50	
51	    private final ToLongFunction<? super ClientRequestContext> requestContextHasher;
52	
53	    /**
54	     * Creates a new {@link StickyEndpointSelectionStrategy}
55	     * with provided hash function to hash a {@link ClientRequestContext} to a {@code long}.
56	     *
57	     * @param requestContextHasher The default {@link ToLongFunction} of {@link ClientRequestContext}
58	     */
59	    StickyEndpointSelectionStrategy(ToLongFunction<? super ClientRequestContext> requestContextHasher) {
60	        this.requestContextHasher = requireNonNull(requestContextHasher, "requestContextHasher");
61	    }
62	
63	    /**
64	     * Creates a new {@link StickyEndpointSelector}.
65	     *
66	     * @param endpointGroup an {@link EndpointGroup}
67	     * @return a new {@link StickyEndpointSelector}
68	     */
69	    @Override
70	    public EndpointSelector newSelector(EndpointGroup endpointGroup) {
71	        return new StickyEndpointSelector(endpointGroup, requestContextHasher);
72	    }
73	
74	    private static final class StickyEndpointSelector extends AbstractEndpointSelector {
75	
76	        private final ToLongFunction<? super ClientRequestContext> requestContextHasher;
77	
78	        StickyEndpointSelector(EndpointGroup endpointGroup,
79	                               ToLongFunction<? super ClientRequestContext> requestContextHasher) {
80	            super(endpointGroup);
81	            this.requestContextHasher = requireNonNull(requestContextHasher, "requestContextHasher");
82	            initialize();
83	        }
84	
85	        @Nullable
86	        @Override
87	        public Endpoint selectNow(ClientRequestContext ctx) {
88	            final List<Endpoint> endpoints = group().endpoints();
89	            if (endpoints.isEmpty()) {
90	                return null;
91	            }
92	
93	            final long key = requestContextHasher.applyAsLong(ctx);
94	            final int nearest = Hashing.consistentHash(key, endpoints.size());
95	            return endpoints.get(nearest);
96	        }
97	
98	        @Override
99	        public String toString() {
100	            return MoreObjects.toStringHelper(this)
101	                              .add("endpoints", group().endpoints())
102	                              .toString();
103	        }
104	    }
105	}
