37	/**
38	 * This {@link LoadBalancer} selects an element using random and {@link WeightedObject#weight()}.
39	 * If there are A(weight 10), B(weight 4) and C(weight 6) elements, the chances that
40	 * elements are selected are 10/20, 4/20 and 6/20, respectively. If A is selected 10 times and B and C are not
41	 * selected as much as their weight, then A is removed temporarily and the chances that B and C are selected are
42	 * 4/10 and 6/10.
43	 */
44	final class WeightedRandomLoadBalancer<T> implements SimpleLoadBalancer<T> {
45	
46	    private final ReentrantLock lock = new ReentrantShortLock();
47	    private final List<CandidateContext<T>> allEntries;
48	    @GuardedBy("lock")
49	    private final List<CandidateContext<T>> currentEntries;
50	    private final long total;
51	    private long remaining;
52	
53	    WeightedRandomLoadBalancer(Iterable<? extends T> candidates,
54	                               @Nullable ToIntFunction<? super T> weightFunction) {
55	        @SuppressWarnings("unchecked")
56	        final List<CandidateContext<T>> candidateContexts =
57	                Streams.stream((Iterable<T>) candidates)
58	                       .map(e -> {
59	                           if (weightFunction == null) {
60	                               return new CandidateContext<>(e, ((Weighted) e).weight());
61	                           } else {
62	                               return new CandidateContext<>(e, weightFunction.applyAsInt(e));
63	                           }
64	                       })
65	                       .filter(e -> e.weight() > 0)
66	                       .collect(toImmutableList());
67	
68	        total = candidateContexts.stream().mapToLong(CandidateContext::weight).sum();
69	        remaining = total;
70	        allEntries = candidateContexts;
71	        currentEntries = new ArrayList<>(allEntries);
72	    }
73	
74	    @VisibleForTesting
75	    List<CandidateContext<T>> entries() {
76	        return allEntries;
77	    }
78	
79	    @Nullable
80	    @Override
81	    public T pick() {
82	        if (allEntries.isEmpty()) {
83	            return null;
84	        }
85	
86	        final ThreadLocalRandom threadLocalRandom = ThreadLocalRandom.current();
87	        lock.lock();
88	        try {
89	            long target = threadLocalRandom.nextLong(remaining);
90	            final Iterator<CandidateContext<T>> it = currentEntries.iterator();
91	            while (it.hasNext()) {
92	                final CandidateContext<T> entry = it.next();
93	                final int weight = entry.weight();
94	                target -= weight;
95	                if (target < 0) {
96	                    entry.increment();
97	                    if (entry.isFull()) {
98	                        it.remove();
99	                        entry.reset();
100	                        remaining -= weight;
101	                        if (remaining == 0) {
102	                            // As all entries are full, reset `currentEntries` and `remaining`.
103	                            currentEntries.addAll(allEntries);
104	                            remaining = total;
105	                        } else {
106	                            assert remaining > 0 : remaining;
107	                        }
108	                    }
109	                    return entry.get();
110	                }
111	            }
112	        } finally {
113	            lock.unlock();
114	        }
115	
116	        // Since `allEntries` is not empty, should subselect one Endpoint from `allEntries`.
117	        throw new Error("Should never reach here");
118	    }
119	
120	    @SuppressWarnings("GuardedBy")
121	    @Override
122	    public String toString() {
123	        return MoreObjects.toStringHelper(this)
124	                          .add("allEntries", allEntries)
125	                          .add("currentEntries", currentEntries)
126	                          .add("total", total)
127	                          .add("remaining", remaining)
128	                          .toString();
129	    }
130	
131	    @VisibleForTesting
132	    static final class CandidateContext<T> extends WeightedObject<T> {
133	
134	        private int counter;
135	
136	        CandidateContext(T candidate, int weight) {
137	            super(candidate, weight);
138	        }
139	
140	        void increment() {
141	            assert counter < weight();
142	            counter++;
143	        }
144	
145	        void reset() {
146	            counter = 0;
147	        }
148	
149	        int counter() {
150	            return counter;
151	        }
152	
